const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)]
const icon = name => `<svg><use href="#i-${name}"/></svg>`
let toastTimer, checkGeneration = 0, scenario = 'ok', controlling = false, logging = false, stopped = false, autoPaused = true, settingsCategory = 'general'
const bots = new Map(), drafts = new Map()
const initialSettings = () => ({interest:'爱看中国明星的舞台、综艺切片，还有韩国女团的直拍和练舞。喜欢猫猫狗狗、搞笑视频、穿搭和美食，遇到有意思的就分享给主人。',interval:5,total:60,auto:false,headless:false})
const current = () => bots.get($('#bot').value)
for (const name of ['林诗语','大肥鱼']) bots.set(name, initialSettings())
function toast(message){ $('#toast').textContent=message; $('#toast').hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').hidden=true,2800) }
function open(id){const d=$('#'+id);if(!d.open)d.showModal()}
function close(id){$('#'+id).close()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const navigation=[['grid','概览'],['chat','对话记录'],['file','记忆'],['file','日记'],['globe','浏览器'],['clock','主动消息'],['sliders','角色设置']]
$('#navigation').innerHTML=navigation.map(([i,n])=>`<button ${n==='浏览器'?'class="selected"':''} data-demo="${n}">${icon(i)}${n}</button>`).join('')
const taskData=[['running','按自己的兴趣刷一会儿抖音','今天 21:46 · 已看 8 条 · 运行 06:42','浏览中'],['done','看看最近女团的回归舞台','今天 20:18 · 看了 12 条 · 分享 2 条','已完成'],['blocked','寻找有趣的小动物视频','今天 18:52 · 碰到账户验证，已提醒主人','需处理'],['done','刷一会儿推荐视频','今天 18:05 · 看了 16 条 · 点赞 3 次','已完成']]
const interactions=[{type:'分享',title:'这个直拍的舞台灯光也太漂亮了',meta:'今天 21:48 · 已送达 Owner 会话',status:'confirmed'}, {type:'评论',title:'猫猫的耳朵被太阳照得透亮',meta:'今天 21:44 · 平台回执待核验',status:'unknown'}, {type:'点赞',title:'窗边午睡的小猫',meta:'今天 21:43 · 等待读取点赞状态',status:'unknown'}, {type:'私信',title:'回复主人的未读消息',meta:'今天 21:40 · 已确认发送',status:'confirmed'}]
function renderTasks(filter='all'){ $('#task-records').innerHTML=taskData.filter(t=>filter==='all'||t[0]===filter).map(t=>`<article class="record">${icon(t[0]==='blocked'?'lock':'play')}<div class="record-main"><b>${esc(t[1])}</b><p>${esc(t[2])}</p></div><span class="badge ${t[0]==='blocked'?'warning':''}">${t[3]}</span><button class="button" data-action="task-detail">查看</button></article>`).join('') }
function renderInteractions(filter='all'){const pending=interactions.filter(i=>i.status==='unknown').length;$('.pending-count').textContent=pending?`${pending} 待核对`:'全部已核对';$('[data-interaction-filter=unknown] .count').textContent=pending;$('#interaction-records').innerHTML=interactions.map((i,index)=>({...i,index})).filter(i=>filter==='all'||i.status===filter).map(i=>`<article class="record">${icon(i.type==='点赞'?'heart':i.type==='分享'?'share':'chat')}<div class="record-main"><b>${esc(i.title)}</b><p>${esc(i.type)} · ${esc(i.meta)}</p></div><span class="badge ${i.status==='unknown'?'warning':''}">${i.status==='unknown'?'待核对':'已确认'}</span>${i.status==='unknown'?`<button class="button" data-verify="${i.index}">核对结果</button>`:''}</article>`).join('')||'<div class="empty">没有此类记录</div>'}
renderTasks();renderInteractions()
const settingsCategories={general:'浏览偏好',schedule:'自动浏览',interaction:'互动权限',browser:'浏览器',experimental:'实验性功能'}
function collectDraft(){const d=drafts.get($('#bot').value);if(!d)return;$$('#settings-form [name]').forEach(el=>d[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value)}
function settings(category='general'){if($('#settings-dialog').open)collectDraft();else drafts.set($('#bot').value,{...current()});settingsCategory=category;$('#settings-nav').innerHTML=Object.entries(settingsCategories).map(([key,name])=>`<button class="${category===key?'selected':''}" data-category="${key}">${name}</button>`).join('');const d=drafts.get($('#bot').value);let fields='';if(category==='general')fields=`<label>她的兴趣<textarea name="interest" rows="5">${esc(d.interest)}</textarea></label><small>由你填写，她可以顺着兴趣探索，也可以发现新的喜欢。</small><label>每次任务最多运行（分钟）<input type="number" value="20" min="1" max="120"></label>`;if(category==='schedule')fields=`<label class="toggle-row">空闲时段自动浏览<input name="auto" type="checkbox" ${d.auto?'checked':''}></label><small>北京时间周一至周五 9:00–12:00、14:00–18:00 为高峰；其余时间、周末和中国法定节假日为空闲。进入高峰后完成当前操作即暂停。</small><label>每日视频总数<input name="total" type="number" min="1" max="1000" value="${d.total}"></label><small>按实际播放过的不同视频计数，重复打开不重复计入。北京时间零点重置。</small>`;if(category==='interaction')fields=`<label class="toggle-row">允许点赞<input type="checkbox" checked></label><label class="toggle-row">允许评论<input type="checkbox" checked></label><label class="toggle-row">允许分享给主人<input type="checkbox" checked></label><label class="toggle-row">允许回复私信<input type="checkbox" checked></label><label>私信检查间隔（秒）<input name="interval" type="number" min="1" max="300" value="${d.interval}"></label><small>后台检查未读消息，不切走当前视频。回复沿用账号权限和额度限制。</small>`;if(category==='browser')fields=`<label>启动模式<select disabled><option>普通 Chrome（默认）</option></select></label><small>使用本机官方 Chrome，可能显示浏览器窗口和 Dock 图标。每个 Bot 单独保存登录资料。</small><label>画面清晰度<select><option>原始画质 · 1600 × 900</option><option>流畅 · 较低带宽</option></select></label><button type="button" class="button" data-action="check">重新检测运行环境</button>`;if(category==='experimental')fields=`<label class="toggle-row">无头模式 headless<input name="headless" type="checkbox" ${d.headless?'checked':''}></label><small>开启后隐藏 Chrome 窗口，仍可在工作台实时查看和接管。部分网站可能出现访问异常、额外登录验证或风控拦截；不能保证解决小红书 300012。停止浏览器后切换，下次启动生效。</small>`;$('#settings-form').innerHTML=`<h3>${settingsCategories[category]}</h3>${fields}`;open('settings-dialog')}
function controls(){ $('#viewer').classList.toggle('controlling',controlling);$('#address').readOnly=!controlling;$('.takeover span').textContent=controlling?'结束接管':'接管浏览器';$('#browser-state').textContent=stopped?'浏览器已停止':logging?'主人登录中':controlling?'你正在接管':'Bot 正在浏览';$('#control-hint').textContent=controlling?'模型已暂停操作':'接管后可操作页面';$('#login-banner').hidden=!logging;$('.login-button span').textContent=logging?'完成登录':'主人登录';$('#stopped-cover').hidden=!stopped }
const wait=ms=>new Promise(r=>setTimeout(r,ms))
async function check(mode='ok'){scenario=mode;const generation=++checkGeneration;open('environment-dialog');$('#env-title').textContent='正在准备浏览器';$('#env-subtitle').textContent='检查这台电脑的运行环境 · 原型模拟';$('#install-help').hidden=true;$('#env-retry').hidden=true;$('#env-result').textContent='正在检测…';const rows=[['系统与架构','macOS · Apple Silicon'],['Node.js 运行环境','Node.js 22.x'],['浏览器运行服务','连接正常'],['Google Chrome','已安装'],['资料目录与启动权限','正常']];$('#check-list').innerHTML=rows.map(([name],i)=>`<div class="check-row" id="check-${i}"><span>·</span><b>${name}</b><small>等待检测</small></div>`).join('');for(let i=0;i<rows.length;i++){if(generation!==checkGeneration)return;const row=$('#check-'+i);row.classList.add('pending');row.querySelector('small').textContent='检测中';await wait(320);if(generation!==checkGeneration)return;row.classList.remove('pending');const fail=mode==='node-missing'&&i===1||mode==='disconnected'&&i===2||mode==='chrome-missing'&&i===3;row.querySelector('span').textContent=fail?'!':'✓';row.querySelector('small').textContent=fail?'需要处理':rows[i][1];if(fail){row.classList.add('error');$('#env-title').textContent=mode==='disconnected'?'浏览器服务尚未连接':'还差一步就能开始';$('#env-result').textContent='完成后点击重新检测';$('#env-retry').hidden=false;const help=$('#install-help');help.hidden=false;help.innerHTML=mode==='node-missing'?'<b>先安装 Node.js</b><p>浏览器功能需要 Node.js 才能运行。安装完成后，再启动 HayBot 浏览器服务。</p><ol><li>打开官网，选择 Node.js 22.x LTS 的安装包。</li><li>macOS 下载 .pkg，Windows 下载 .msi，按安装器提示完成。</li><li>重新打开 HayBot 启动入口，再回到这里检测。</li></ol><a class="button primary" href="https://nodejs.org/en/download" target="_blank" rel="noopener">前往 Node.js 官方下载</a><p>此处演示安装引导，不会实际检查或安装软件。</p>':mode==='chrome-missing'?'<b>安装官方 Google Chrome</b><p>打开中国官网下载安装，完成后返回重新检测。已有登录资料会保留。</p><a class="button primary" href="https://www.google.cn/chrome/" target="_blank" rel="noopener">前往 Chrome 中国官网</a>':'<b>Node.js 已就绪，浏览器服务还没启动</b><p>请打开 HayBot 的浏览器服务启动入口。若你已启动，检查服务窗口的报错，再重试连接。</p><p>此处为原型状态演示，正式启动前检查和一键启动入口尚待实现。</p>';return;}}
$('#env-title').textContent='环境已就绪';$('#env-result').textContent='检测通过，即将进入工作台';await wait(650);if(generation===checkGeneration)close('environment-dialog')}
$('#environment-dialog').addEventListener('close',()=>checkGeneration++)
$('#environment-dialog').addEventListener('cancel',()=>checkGeneration++)
const actions={theme(){document.documentElement.classList.toggle('dark')},nav(){$('#sidebar').classList.toggle('open')},settings(){settings()},'schedule-settings'(){settings('schedule')},'new-task'(){open('new-task-dialog')},takeover(){if(stopped)return toast('请先启动浏览器');if(logging)return toast('请先完成主人登录');controlling=!controlling;controls()},login(){if(logging)open('confirm-dialog');else{logging=true;controls()}},'finish-login'(){logging=false;close('confirm-dialog');controls()},more(){const m=$('#more-menu');m.hidden=!m.hidden;$('[data-action=more]').setAttribute('aria-expanded',String(!m.hidden))},expand(){$('#viewer').classList.toggle('expanded')},reconnect(){toast('原型：已重新连接画面')},quality(){settings('browser')},check(){check()},'retry-check'(){toast('原型演示：模拟安装完成后重新检测');check()},'node-missing'(){check('node-missing')},'chrome-missing'(){check('chrome-missing')},disconnected(){check('disconnected')},stop(){if(logging)return toast('请先完成主人登录');stopped=!stopped;controlling=false;controls()},auto(){autoPaused=!autoPaused;$('[data-action=auto]').textContent=autoPaused?'已暂停 · 恢复':'自动运行 · 暂停';toast('原型：'+(autoPaused?'已暂停自动浏览':'已恢复自动浏览'))},'pause-task'(){$('#task-strip-state').textContent='已停止';toast('原型：当前任务已停止')},'task-detail'(){$('#detail-title').textContent='任务进度';$('#detail-body').innerHTML='<span class="badge">浏览中</span><h3 style="margin-top:20px">按自己的兴趣刷一会儿抖音</h3><p>今天 21:46 开始 · 已看 8 条</p>'+['打开推荐页，看看现在有什么内容','发现喜欢的女团舞台，完整观看','看到可爱的小猫，确认点赞结果','将有趣的舞台视频分享给主人','继续浏览，等待新的内容'].map((s,i)=>`<div class="detail-step"><span class="subtle">${i+1}　${i<4?'已完成':'进行中'}</span><p>${s}</p></div>`).join('');open('detail-dialog')},verification(){controlling=false;controls();$('#browser-state').textContent='需要主人验证';$('#task-strip-state').textContent='已暂停 · 等待验证';$('#detail-title').textContent='需要你帮忙验证';$('#detail-body').innerHTML='<h3>宝宝，我刷抖音又碰到账户验证了</h3><p>帮我去浏览器接管一下好不好？验证完我再接着看。</p><p>任务已暂停。接管后开启“主人登录”，完成验证并离开验证码页面，再点击“完成登录”。</p><button class="button primary" data-action="verify-takeover">接管并进入主人登录</button>';open('detail-dialog')},'verify-takeover'(){controlling=true;logging=true;controls();close('detail-dialog')},'save-settings'(){collectDraft();const d=drafts.get($('#bot').value);if(!Number.isFinite(d.interval)||d.interval<1||d.interval>300||!Number.isFinite(d.total)||d.total<1||d.total>1000)return toast('请检查数量和间隔的范围');if(d.headless&&!current().headless&&!confirm('开启无头模式可能导致网站访问异常、额外登录验证或风控拦截。实时查看和接管会保留。确认开启？'))return;if(d.headless!==current().headless&&!stopped)return toast('切换无头模式前，请先停止浏览器');bots.set($('#bot').value,{...d});close('settings-dialog');toast('原型：已保存当前 Bot 的设置（仅本次预览）')},search(){toast('当前原型仅展示浏览器工作台')},'tab-add'(){toast('原型：新建空白标签页');$('#address').value='about:blank'},'tab-close'(){toast('原型：已关闭当前标签页');$('#address').value='www.douyin.com'}}
document.addEventListener('click',e=>{const closeButton=e.target.closest('[data-close]');if(closeButton){close(closeButton.dataset.close);return}const action=e.target.closest('[data-action]');if(action){if(action.dataset.action!=='more'){$('#more-menu').hidden=true;$('[data-action=more]').setAttribute('aria-expanded','false')}actions[action.dataset.action]?.();return}const page=e.target.closest('[data-page]');if(page){$$('[data-page]').forEach(b=>b.setAttribute('aria-selected',String(b===page)));$$('.page-view').forEach(v=>v.hidden=v.id!=='page-'+page.dataset.page);return}const cat=e.target.closest('[data-category]');if(cat)return settings(cat.dataset.category);const filter=e.target.closest('[data-filter]');if(filter){$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b===filter));renderTasks(filter.dataset.filter);return}const intFilter=e.target.closest('[data-interaction-filter]');if(intFilter){$$('[data-interaction-filter]').forEach(b=>b.classList.toggle('selected',b===intFilter));renderInteractions(intFilter.dataset.interactionFilter);return}const verify=e.target.closest('[data-verify]');if(verify){const item=interactions[Number(verify.dataset.verify)];item.status='confirmed';item.meta='刚刚 · 模拟平台只读核验通过';renderInteractions($('.segmented [data-interaction-filter].selected').dataset.interactionFilter);toast('原型：已核对原操作结果，没有重新发送');return}const site=e.target.closest('[data-site]');if(site){$$('[data-site]').forEach(b=>{b.classList.toggle('selected',b===site);b.setAttribute('aria-selected',String(b===site))});$('#address').value=site.dataset.site==='douyin'?'www.douyin.com':'www.bilibili.com';toast('原型：标签页已切换，画面为合成示意');return}const prompt=e.target.closest('[data-prompt]');if(prompt){$('#task-goal').value=prompt.dataset.prompt;return}const demo=e.target.closest('[data-demo]');if(demo)toast('原型：'+demo.dataset.demo)})
$('#bot').addEventListener('change',()=>{$$('.bot-name').forEach(el=>el.textContent=$('#bot').value);toast('已切换 Bot · 设置按 Bot 独立演示')})
$('#new-task-form').addEventListener('submit',e=>{e.preventDefault();$('#task-strip-title').textContent=$('#task-goal').value;$('#task-strip-state').textContent='浏览中';close('new-task-dialog');toast('原型：已创建演示任务，没有运行真实浏览任务')})
$('#address-form').addEventListener('submit',e=>{e.preventDefault();toast('原型：前往 '+$('#address').value)})
$('#typing-form').addEventListener('submit',e=>{e.preventDefault();toast('原型：文字已输入网页');$('#typing-form input').value=''})
$('#settings-form').addEventListener('submit',e=>e.preventDefault())
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#viewer').classList.remove('expanded');if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();actions.search()}})
controls();check()
